mapper.select:
SELECT ROLE_ID
FROM T_RELATIONSHIP_ROLE
WHERE KINDERGARTEN_ID = #{kindergartenId}
  AND USER_ID = #{userId}
ORDER BY ROLE_ID

SELECT COUNT(*) > 0 AS `EXISTS`
FROM T_RELATIONSHIP
WHERE KINDERGARTEN_ID = #{kindergartenId}
  AND USER_ID = #{userId}

SELECT R.KINDERGARTEN_ID, R.USER_ID, U.NAME USER_NAME, R.TYPE, R.CLASS_ID, R.ROLE_ID, R.NICKNAME,
       UNIX_TIMESTAMP(R.CREATED_AT) * 1000 CREATED_AT, UNIX_TIMESTAMP(R.UPDATED_AT) * 1000 UPDATED_AT
FROM T_RELATIONSHIP R
JOIN T_USER U ON U.ID = R.USER_ID
WHERE R.KINDERGARTEN_ID = #{kindergartenId}
  AND R.USER_ID = #{userId}

mapper.update:
UPDATE T_RELATIONSHIP
SET ROLE_ID = #{roleId}
WHERE KINDERGARTEN_ID = #{kindergartenId}
  AND USER_ID = #{userId}

UPDATE T_RELATIONSHIP
SET CLASS_ID = #{classId}
WHERE KINDERGARTEN_ID = #{kindergartenId}
  AND USER_ID = #{userId}

UPDATE T_RELATIONSHIP
SET NICKNAME = #{nickname}
WHERE KINDERGARTEN_ID = #{kindergartenId}
  AND USER_ID = #{userId}

mapper.delete:
DELETE FROM T_RELATIONSHIP_ROLE
WHERE KINDERGARTEN_ID = #{kindergartenId}
  AND USER_ID = #{userId}
  AND ROLE_ID = #{roleId}

DELETE FROM T_RELATIONSHIP_ROLE
WHERE KINDERGARTEN_ID = #{kindergartenId}
  AND USER_ID = #{userId}

DELETE FROM T_RELATIONSHIP
WHERE KINDERGARTEN_ID = #{kindergartenId}
  AND USER_ID = #{userId}
